function validate(input) {
  const [{ Salary = [] }] = input;
  const seen = new Set(), details = new Map();
  for (const [emp, first, last, salary, dept] of Salary) {
    if (emp === null || salary === null) return 'Every row needs an emp_id and a salary.';
    if (salary <= 0) return `Employee ${emp} has a salary of ${salary}; salaries are positive.`;
    const key = `${emp}:${salary}`;
    if (seen.has(key)) return `Employee ${emp} has salary ${salary} twice.`;
    seen.add(key);
    const who = JSON.stringify([first, last, dept]);
    if (details.has(emp) && details.get(emp) !== who) return `Employee ${emp} has different names or departments in different rows.`;
    details.set(emp, who);
  }
  return null;
}

