function generate(rand, size) {
  const small = size === 'small';
  const firsts = ['Todd', 'Justin', 'Kelly', 'Patricia', 'Sherry', 'Natasha', 'Omar'];
  const lasts = ['Wilson', 'Simon', 'Rosario', 'Powell', 'Golden', 'Swanson'];
  const employees = small ? Math.floor(rand() * 5) : 600;
  const pick = list => list[Math.floor(rand() * list.length)];
  const rows = [];
  for (let i = 0; i < employees; i++) {
    // Ids are sparse so that the order by emp_id is not the insertion order.
    const emp = small ? i * 3 + 1 + Math.floor(rand() * 3) : i + 1;
    const first = pick(firsts), last = pick(lasts), dept = `D100${1 + Math.floor(rand() * 6)}`;
    const count = 1 + Math.floor(rand() * 3), used = new Set();
    for (let k = 0; k < count && (!small || rows.length < 8); k++) {
      const salary = small ? 40000 + 10000 * Math.floor(rand() * 8) : 30000 + Math.floor(rand() * 150000);
      if (used.has(salary)) continue;
      used.add(salary);
      rows.push([emp, first, last, salary, dept]);
    }
  }
  for (let i = rows.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ Salary: rows }];
}
